local LeatherCoverMaker = {}
local PRODUCTS = {
    iron_leather_cover = { name = "Železna usnjena platnica", ironCost = 1, woodCost = 1, leatherCost = 5, time = 6, cost = 185, prestige = 4, happiness = 2, description = "Železna usnjena platnica za knjige." },
    bronze_leather_cover = { name = "Bronasta usnjena platnica", bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 5, time = 8, cost = 445, prestige = 6, happiness = 3, description = "Bronasta usnjena platnica za trdne knjige." },
    silver_leather_cover = { name = "Srebrna usnjena platnica", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 5, time = 12, cost = 1070, prestige = 11, happiness = 4, description = "Srebrna usnjena platnica za plemiške knjige." },
    gilded_leather_cover = { name = "Pozlačena usnjena platnica", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 5, time = 16, cost = 2300, prestige = 20, happiness = 5, description = "Pozlačena usnjena platnica za dvorne knjige." },
    jewel_set_leather_cover = { name = "Draguljasta usnjena platnica", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 5, time = 20, cost = 4950, prestige = 36, happiness = 7, description = "Draguljasta usnjena platnica za kraljevske knjige." },
    royal_sovereign_leather_cover = { name = "Kraljevski suverena usnjena platnica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 6, time = 27, cost = 10600, prestige = 69, happiness = 13, description = "Suverena usnjena platnica z biseri za krono." },
}
local BUILDINGS = {
    leathercover_workshop = { name = "Platnična delavnica", cost = { gold = 370, wood = 175, stone = 145, iron = 6 }, upkeep = 7, qualityBonus = 5 },
    leathercover_house = { name = "Platnična hiša", cost = { gold = 1285, wood = 360, stone = 290, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_leathercover_atelier = { name = "Mojstrski platnični atelje", cost = { gold = 3200, wood = 420, stone = 545, silver = 39, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_leathercover_palace = { name = "Suverena platnična palača", cost = { gold = 13600, wood = 650, stone = 860, gold = 88, jewel = 20 }, upkeep = 263, qualityBonus = 55, prestigeBonus = 50 },
}
LeatherCoverMaker.ironStock = 10; LeatherCoverMaker.bronzeStock = 8; LeatherCoverMaker.woodStock = 12; LeatherCoverMaker.leatherStock = 20; LeatherCoverMaker.silverStock = 8; LeatherCoverMaker.goldStock = 6; LeatherCoverMaker.jewelStock = 4; LeatherCoverMaker.pearlStock = 4
LeatherCoverMaker.productStock = {}; LeatherCoverMaker.buildings = {}; LeatherCoverMaker.maker = nil; LeatherCoverMaker.activeMaking = {}; LeatherCoverMaker.totalProducts = 0; LeatherCoverMaker.dayTimer = 0
function LeatherCoverMaker.init() LeatherCoverMaker.ironStock=10; LeatherCoverMaker.bronzeStock=8; LeatherCoverMaker.woodStock=12; LeatherCoverMaker.leatherStock=20; LeatherCoverMaker.silverStock=8; LeatherCoverMaker.goldStock=6; LeatherCoverMaker.jewelStock=4; LeatherCoverMaker.pearlStock=4; LeatherCoverMaker.productStock={}; LeatherCoverMaker.buildings={}; LeatherCoverMaker.maker=nil; LeatherCoverMaker.activeMaking={}; LeatherCoverMaker.totalProducts=0; LeatherCoverMaker.dayTimer=0; print("[LeatherCoverMaker] Royal Leather Cover Maker System initialized (6 products, 4 buildings)") end
function LeatherCoverMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LeatherCoverMaker.maker={name=n or ("Platničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Platničar najet: %s (spretnost: %d)",LeatherCoverMaker.maker.name,s),"success") end; return true end
function LeatherCoverMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LeatherCoverMaker.build(id) local ok,e=LeatherCoverMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LeatherCoverMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LeatherCoverMaker.getQualityBonus() local b=0; for _,bd in ipairs(LeatherCoverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LeatherCoverMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and LeatherCoverMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and LeatherCoverMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and LeatherCoverMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LeatherCoverMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LeatherCoverMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LeatherCoverMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LeatherCoverMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LeatherCoverMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LeatherCoverMaker.buildings==0 then return false,"Potrebna platnična delavnica" end; if not LeatherCoverMaker.maker then return false,"Potreben platničar" end; return true end
function LeatherCoverMaker.make(pt,qty) qty=qty or 1; local ok,e=LeatherCoverMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then LeatherCoverMaker.ironStock=LeatherCoverMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then LeatherCoverMaker.bronzeStock=LeatherCoverMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then LeatherCoverMaker.woodStock=LeatherCoverMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LeatherCoverMaker.leatherStock=LeatherCoverMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LeatherCoverMaker.silverStock=LeatherCoverMaker.silverStock-d.silverCost*qty end; if d.goldCost then LeatherCoverMaker.goldStock=LeatherCoverMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LeatherCoverMaker.jewelStock=LeatherCoverMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LeatherCoverMaker.pearlStock=LeatherCoverMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LeatherCoverMaker.maker then t=math.max(1,t-math.floor(LeatherCoverMaker.maker.skill/13)) end; table.insert(LeatherCoverMaker.activeMaking,{id="leathercover_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LeatherCoverMaker.completeMaking(m) local q=1.0+(LeatherCoverMaker.getQualityBonus()/100); if LeatherCoverMaker.maker then q=q+(LeatherCoverMaker.maker.skill/140) end; q=math.min(2.5,q); LeatherCoverMaker.productStock[m.productType]=(LeatherCoverMaker.productStock[m.productType] or 0)+m.quantity; LeatherCoverMaker.totalProducts=LeatherCoverMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LeatherCoverMaker.maker then LeatherCoverMaker.maker.itemsMade=LeatherCoverMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LeatherCoverMaker.maker.skill=math.min(100,LeatherCoverMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Platnica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"leathercover.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function LeatherCoverMaker.update(dt) if not _G.state then return end; LeatherCoverMaker.dayTimer=LeatherCoverMaker.dayTimer+dt; if LeatherCoverMaker.dayTimer>=30 then LeatherCoverMaker.dayTimer=0; for i=#LeatherCoverMaker.activeMaking,1,-1 do local m=LeatherCoverMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LeatherCoverMaker.completeMaking(m); table.remove(LeatherCoverMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LeatherCoverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LeatherCoverMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LeatherCoverMaker.getStats() return {ironStock=LeatherCoverMaker.ironStock,bronzeStock=LeatherCoverMaker.bronzeStock,woodStock=LeatherCoverMaker.woodStock,leatherStock=LeatherCoverMaker.leatherStock,silverStock=LeatherCoverMaker.silverStock,goldStock=LeatherCoverMaker.goldStock,jewelStock=LeatherCoverMaker.jewelStock,pearlStock=LeatherCoverMaker.pearlStock,productStock=LeatherCoverMaker.productStock,numBuildings=#LeatherCoverMaker.buildings,hasMaker=LeatherCoverMaker.maker~=nil,makerName=LeatherCoverMaker.maker and LeatherCoverMaker.maker.name or "—",makerSkill=LeatherCoverMaker.maker and LeatherCoverMaker.maker.skill or 0,activeMaking=#LeatherCoverMaker.activeMaking,totalProducts=LeatherCoverMaker.totalProducts} end
return LeatherCoverMaker
